INSERT INTO news (id, title, body, category, pin, created_at) VALUES
(1,'เปิดรับสมัครนักเรียนใหม่ ปีการศึกษา 2568','แผนกคหกรรมเปิดรับสมัครนักเรียนใหม่ประจำปีการศึกษา 2568 ตั้งแต่บัดนี้ถึงวันที่ 30 กันยายน 2568 สามารถสมัครได้ทางออนไลน์หรือที่แผนกโดยตรง','ประกาศสำคัญ',1,'2026-07-20 08:00:00'),
(2,'นักเรียนคว้ารางวัลชนะเลิศการแข่งขันทำอาหารระดับจังหวัด','ขอแสดงความยินดีกับทีมนักเรียนแผนกคหกรรมที่ได้รับรางวัลชนะเลิศในการแข่งขันยอดฝีมืออาหารไทยระดับจังหวัด ประจำปี 2568','ความสำเร็จ',1,'2026-07-25 10:00:00'),
(3,'เปิดโครงการครัวชุมชน บริการอาหารราคาประหยัดแก่ชุมชน','นักเรียนแผนกคหกรรมออกบริการชุมชน จัดทำอาหารกลางวันสำหรับผู้สูงอายุในชุมชนใกล้เคียง ทุกวันศุกร์ตลอดเดือนสิงหาคม','กิจกรรม',0,'2026-08-05 08:30:00'),
(4,'เชิญชวนร่วมงานนิทรรศการผ้าและแฟชั่น ประจำปี 2568','จัดแสดงผลงานนักเรียนสาขาผ้าและเครื่องแต่งกาย พบกับคอลเลกชันพิเศษที่สร้างสรรค์โดยนักเรียนทุกชั้นปี','กิจกรรม',0,'2026-08-04 09:00:00'),
(5,'อบรมเชิงปฏิบัติการ ดอกไม้สดสำหรับงานมงคล','เรียนรู้เทคนิคการจัดดอกไม้สำหรับงานมงคลต่างๆ จากผู้เชี่ยวชาญ เปิดรับสมัครบัดนี้ถึง 20 สิงหาคม 2568','อบรม',0,'2026-08-01 09:00:00'),
(6,'ประกาศตารางสอบปลายภาค 2/2567','ประกาศตารางสอบปลายภาคเรียนที่ 2 ปีการศึกษา 2567 นักเรียนสามารถตรวจสอบรายละเอียดได้ที่ประกาศนียบัตรแผนก','ประกาศ',0,'2026-08-03 13:00:00');
